import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';


export interface TransactionPreviewData {
    data: any;
    onConfirm: () => void | Promise<void>;
    onCancel?: () => void;
}

@Injectable({
    providedIn: 'root'
})
export class TransactionPreviewService {
    private previewSubject = new Subject<TransactionPreviewData | null>();
    public preview$ = this.previewSubject.asObservable();

    /**
     * Show transaction preview modal
     * @param data Transaction data to display (will be JSON stringified)
     * @param onConfirm Callback to execute if user confirms
     * @param onCancel Optional callback if user cancels
     */
    show(data: any, onConfirm: () => void | Promise<void>, onCancel?: () => void) {
        this.previewSubject.next({ data, onConfirm, onCancel });
    }

    /**
     * Close the preview modal
     */
    close() {
        this.previewSubject.next(null);
    }

    constructor() {
    }
}
