import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { ethers } from 'ethers';
import { TxSignPayload } from './ops.service';
import { Subject, firstValueFrom } from 'rxjs';
import { ContractService } from './contract.service';
import { TransactionPreviewService } from './transaction-preview.service';


export interface TransactionRequest {
    to: string;
    data?: string;
    value?: bigint;
    from?: string;
    metadata?: {
        operation: string;
        contract?: string;
        function?: string;
        args?: any;
    };
    suggestedOfflineSender?: string; // Optional: prepopulate custom sender if different from connected account
    forceMode?: TransactionMode; // Bypass modal and force a specific mode
}

export enum TransactionMode {
    DIRECT = 'DIRECT',       // Send via MetaMask
    OFFLINE = 'OFFLINE'      // Generate QR for offline signing
}

export interface ModeSelectionRequest {
    txRequest: TransactionRequest;
    txPayload?: TxSignPayload;
}

@Injectable({
    providedIn: 'root'
})
export class TransactionInterceptorService {
    private modeSelectionSubject = new Subject<ModeSelectionRequest | null>();
    public modeSelection$ = this.modeSelectionSubject.asObservable();

    private modeResponseSubject = new Subject<TransactionMode | null>();

    // Sender address selection for offline mode
    private senderRequestSubject = new Subject<{ connectedAccount: string; suggestedAddress?: string; provider: ethers.Provider } | null>();
    public senderRequest$ = this.senderRequestSubject.asObservable();

    private senderResponseSubject = new Subject<string | null>();

    // Current context for offline signing
    private currentUnsignedTx: TxSignPayload | TxSignPayload[] | null = null;

    // Subject for pending offline transaction broadcasts
    private offlineTxResponseSubject = new Subject<ethers.TransactionReceipt | null>();

    constructor(private router: Router, private contractService: ContractService, private previewService: TransactionPreviewService) { }

    /**
     * Execute a transaction with user choice between Direct and Offline modes
     */
    async executeTransaction(
        requestOrRequests: TransactionRequest | TransactionRequest[],
        signerOrProvider: ethers.Signer | ethers.Provider
    ): Promise<any | null> {
        const requests = Array.isArray(requestOrRequests) ? requestOrRequests : [requestOrRequests];
        if (requests.length === 0) return null;

        const firstRequest = requests[0];
        // Get the 'from' address for MetaMask (direct mode)
        let metaMaskAddress = '';
        try {
            // Try to get address from signer
            if ('getAddress' in signerOrProvider && typeof signerOrProvider.getAddress === 'function') {
                metaMaskAddress = await signerOrProvider.getAddress();
            }
            // If it's a provider (not connected), metaMaskAddress remains empty
        } catch (e) {
            // Ignore error, metaMaskAddress remains empty.
            // Direct mode execution will fail later if address is required,
            // but Offline mode will properly prompt for the sender.
        }

        // Use forceMode if provided from the first request (assuming homogenous), otherwise ask user
        let mode: TransactionMode | null | undefined = firstRequest.forceMode;
        if (!mode) {
            mode = await this.askUserForMode({ txRequest: firstRequest });
        }

        if (!mode) {
            // User cancelled
            return null;
        }

        if (mode === TransactionMode.DIRECT) {
            // Execute directly via MetaMask sequentially
            let lastTx = null;
            for (const req of requests) {
                lastTx = await this.executeDirect(req, signerOrProvider as ethers.Signer);
                if (requests.length > 1 && lastTx && typeof lastTx.wait === 'function') {
                    // Wait for the Tx to be mined before executing the next one
                    // to ensure nonce and state dependency correctness
                    await lastTx.wait();
                }
            }
            return lastTx; // Return the last receipt/tx
        } else {
            // OFFLINE MODE: Ask for sender address first
            const offlineSender = await this.askForSenderAddress(metaMaskAddress, firstRequest.suggestedOfflineSender);

            if (!offlineSender) {
                // User cancelled sender selection
                return null;
            }

            // Build transaction payloads with OFFLINE sender's nonces
            const txPayloads: TxSignPayload[] = [];

            // Fetch initial nonce and fees once
            let provider = this.contractService.getRpcProvider();
            let [nonce, feeData, network] = await Promise.all([
                provider.getTransactionCount(offlineSender, 'latest'),
                provider.getFeeData(),
                provider.getNetwork()
            ]);

            for (let i = 0; i < requests.length; i++) {
                const req = requests[i];
                const txPayload = await this.buildTransactionPayload(req, offlineSender, nonce + i, feeData, network);
                txPayloads.push(txPayload);
            }

            // Execute offline and wait for broadcast receipt
            return await this.executeOffline(txPayloads.length === 1 ? txPayloads[0] : txPayloads);
        }
    }

    /**
     * Execute transaction directly via MetaMask
     */
    private async executeDirect(
        request: TransactionRequest,
        signer: ethers.Signer
    ): Promise<any> {
        const txData: ethers.TransactionRequest = {
            to: request.to,
            data: request.data,
            value: request.value
        };

        const tx = await signer.sendTransaction(txData);
        return tx;
    }

    /**
     * Execute transaction via offline signing
     */
    private async executeOffline(txPayloadOrPayloads: TxSignPayload | TxSignPayload[]): Promise<any> {
        // Store payload for broadcast page
        this.currentUnsignedTx = txPayloadOrPayloads;

        // Force close any open preview modals before navigating
        this.previewService.close();

        // Navigate to broadcast page
        await this.router.navigate(['/tx-broadcast']);

        // Wait for the broadcast component to resolve the receipt
        const receipt = await firstValueFrom(this.offlineTxResponseSubject);

        if (!receipt) {
            throw new Error('Transaction cancelled or failed');
        }

        return {
            hash: receipt.hash,
            wait: async () => {
                const provider = this.contractService.getRpcProvider();
                return await provider.waitForTransaction(receipt.hash);
            }
        };
    }

    /**
     * Resolve pending offline transaction with a receipt or null (cancelled)
     */
    public resolveOfflineTransaction(receipt: ethers.TransactionReceipt | null) {
        this.offlineTxResponseSubject.next(receipt);
    }

    /**
     * Build unsigned transaction payload
     */
    private async buildTransactionPayload(
        request: TransactionRequest,
        from: string,
        nonce?: number,
        feeData?: ethers.FeeData,
        network?: ethers.Network
    ): Promise<TxSignPayload> {
        let provider = this.contractService.getRpcProvider();

        // Fetch missing properties if not provided (useful for single transactions or first in batch)
        if (nonce === undefined || !feeData || !network) {
            [nonce, feeData, network] = await Promise.all([
                provider.getTransactionCount(from, 'latest'),
                provider.getFeeData(),
                provider.getNetwork()
            ]);
        }

        // Estimate gas
        const txRequest: ethers.TransactionRequest = {
            from,
            to: request.to,
            data: request.data || '0x',
            value: request.value || 0n
        };

        let estimatedGas: bigint;
        try {
            estimatedGas = await provider.estimateGas(txRequest);
        } catch (e) {
            console.warn('Could not estimate gas, using fallback 500k', e);
            estimatedGas = 500000n; // generous fallback for complex offline transactions
        }

        // Add 20% margin to gas estimate
        const gasLimit = (estimatedGas * 120n) / 100n;

        // Build payload
        const payload: TxSignPayload = {
            chainId: Number(network.chainId),
            to: request.to,
            data: request.data || '0x',
            value: (request.value || 0n).toString(),
            nonce: nonce,
            gasLimit: gasLimit.toString(),
            maxFeePerGas: (feeData.maxFeePerGas || 0n).toString(),
            maxPriorityFeePerGas: (feeData.maxPriorityFeePerGas || 0n).toString(),
            from: from,
            metadata: request.metadata
        };

        return payload;
    }

    /**
     * Show modal to ask user for mode selection
     */
    public async askUserForMode(request: ModeSelectionRequest): Promise<TransactionMode | null> {
        // Emit request to show modal
        this.modeSelectionSubject.next(request);

        // Wait for user response
        const mode = await firstValueFrom(this.modeResponseSubject);

        // Clear request
        this.modeSelectionSubject.next(null);

        return mode;
    }

    /**
     * Ask user for sender address in offline mode
     */
    private async askForSenderAddress(
        connectedAccount: string,
        suggestedAddress?: string
    ): Promise<string | null> {
        // Get provider
        // Use direct RPC provider instead of MetaMask for offline operations
        let provider = this.contractService.getRpcProvider();

        // Emit request to show sender modal
        this.senderRequestSubject.next({ connectedAccount, suggestedAddress, provider });

        // Wait for user response
        const sender = await firstValueFrom(this.senderResponseSubject);

        // Clear request
        this.senderRequestSubject.next(null);

        return sender;
    }

    /**
     * Called by modal when user selects a mode
     */
    selectMode(mode: TransactionMode | null): void {
        this.modeResponseSubject.next(mode);
    }

    /**
     * Called by modal when user selects a sender address
     */
    selectSender(address: string | null): void {
        this.senderResponseSubject.next(address);
    }

    /**
     * Get current unsigned transaction (for broadcast page)
     */
    public getCurrentUnsignedTx(): TxSignPayload | TxSignPayload[] | null {
        return this.currentUnsignedTx;
    }

    /**
     * Clear current unsigned transaction
     */
    clearCurrentUnsignedTx(): void {
        this.currentUnsignedTx = null;
    }
}
